fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left: usize = 0;
    let mut right: usize = arr.len();

    while left < right {
        let mid = left + (right - left) / 2;
        if arr[mid] < target {
            left = mid + 1;
        } else {
            // arr[mid] >= target, keep searching left half including mid
            right = mid;
        }
    }

    // After the loop, left == right is the candidate index
    if left < arr.len() && arr[left] == target {
        Some(left)
    } else {
        None
    }
}